def countPairsInRange(nums, lower, upper):
    a = sorted(nums)

    def at_most(x):
        lo, hi = 0, len(a) - 1
        count = 0
        while lo < hi:
            if a[lo] + a[hi] <= x:
                count += hi - lo
                lo += 1
            else:
                hi -= 1
        return count

    return at_most(upper) - at_most(lower - 1)
